def lvl(P):
    side, pair = P['geo']; th = {'AB,AC': 60, 'AB,BC': 120, 'BA,BC': 60, 'CA,CB': 60}[pair]; val = side * side * COS[th]; p, q = pair.split(',')
    o1 = M4(1, 'Triangle \\(ABC\\) is equilateral with side \\(%d\\). Then \\(%s\\cdot%s=\\)…' % (side, ov(*p), ov(*q)), 'Tam giác \\(ABC\\) đều cạnh \\(%d\\). Khi đó \\(%s\\cdot%s=\\)…' % (side, ov(*p), ov(*q)),
            fr(val), [fr(-val), str(side * side), fr(F(side * side, 4))], 'The angle between the vectors is \\(%d^\\circ\\): \\(%d^2\\cos%d^\\circ=%s\\).' % (th, side, th, fr(val)), 'Góc giữa hai vectơ là \\(%d^\\circ\\): \\(%d^2\\cos%d^\\circ=%s\\).' % (th, side, th, fr(val)))
    a, b = P['dot']; d = dot(a, b)
    o2 = M4(2, '\\(\\vec a=%s\\), \\(\\vec b=%s\\). Then \\(\\vec a\\cdot\\vec b=\\)…' % (V2(a), V2(b)), 'Cho \\(\\vec a=%s\\), \\(\\vec b=%s\\). Khi đó \\(\\vec a\\cdot\\vec b=\\)…' % (V2(a), V2(b)),
            str(d), [str(a[0] * b[1] + a[1] * b[0]), str(-d), str(a[0] * b[0] - a[1] * b[1])], '\\(xx′+yy′=%d\\).' % d, '\\(xx′+yy′=%d\\).' % d)
    u, v, ang = P['ang']; c2 = F(dot(u, v) ** 2, dot(u, u) * dot(v, v)); real = 90 if dot(u, v) == 0 else (45 if dot(u, v) > 0 else 135); assert (c2 == F(1, 2) or dot(u, v) == 0) and real == ang
    o3 = M4(3, 'The angle between \\(\\vec u=%s\\) and \\(\\vec v=%s\\) is…' % (V2(u), V2(v)), 'Góc giữa \\(\\vec u=%s\\) và \\(\\vec v=%s\\) bằng…' % (V2(u), V2(v)), '%d^\\circ' % ang, ['%d^\\circ' % x for x in (45, 90, 135, 60) if x != ang],
            '\\(\\cos(\\vec u,\\vec v)=\\dfrac{%d}{\\sqrt{%d}\\cdot\\sqrt{%d}}\\).' % (dot(u, v), dot(u, u), dot(v, v)), '\\(\\cos(\\vec u,\\vec v)=\\dfrac{%d}{\\sqrt{%d}\\cdot\\sqrt{%d}}\\).' % (dot(u, v), dot(u, u), dot(v, v)))
    A, B, C, claim = P['tri']; k = dot(add(B, A, 1, -1), add(C, A, 1, -1)); real = 'acute' if k > 0 else ('right' if k == 0 else 'obtuse')
    W = {'acute': ('acute', 'nhọn'), 'right': ('a right angle', 'vuông'), 'obtuse': ('obtuse', 'tù')}
    t4 = tf(4, 'Three posts of a fence are at \\(A%s\\), \\(B%s\\), \\(C%s\\). The angle \\(\\widehat{BAC}\\) is %s.' % (P2(A), P2(B), P2(C), W[claim][0]), 'Ba cọc rào ở \\(A%s\\), \\(B%s\\), \\(C%s\\). Góc \\(\\widehat{BAC}\\) là góc %s.' % (P2(A), P2(B), P2(C), W[claim][1]), claim == real,
            '\\(\\overrightarrow{AB}\\cdot\\overrightarrow{AC}=%d\\), so the angle is %s.' % (k, W[real][0]), '\\(\\overrightarrow{AB}\\cdot\\overrightarrow{AC}=%d\\) nên góc %s.' % (k, W[real][1]))
    la, lb, th2, c, ok = P['sum']; real_c2 = la * la + lb * lb + 2 * la * lb * COS[th2]; claim_c = c if ok else c + 1; assert real_c2 == c * c
